"""
Hooks pytest para o projeto BUP.
Em caso de falha nos testes de invariantes, imprime as linhas problemáticas
diretamente no terminal para diagnóstico imediato.
"""
from pathlib import Path

import pandas as pd
import pytest

LOG_DIR = Path(__file__).parents[1] / "data" / "logs"


def pytest_configure(config):
    LOG_DIR.mkdir(parents=True, exist_ok=True)


@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_makereport(item, call):
    outcome = yield
    report = outcome.get_result()

    if report.when == "call" and report.failed:
        df = item.funcargs.get("df")
        if df is None:
            return

        linhas = _extrair_linhas_problematicas(item.name, df)
        if linhas is not None and not linhas.empty:
            print(f"\n{'='*60}")
            print(f"  LINHAS PROBLEMATICAS — {item.name}")
            print(f"{'='*60}")
            print(linhas.to_string(index=False))
            print(f"{'='*60}\n")


def _extrair_linhas_problematicas(test_name: str, df: pd.DataFrame) -> pd.DataFrame | None:
    cols_base = ["CNPJ_Cliente", "Nome_Cliente", "Consultor", "Status_Oportunidade", "Dias_Inativo"]
    cols = [c for c in cols_base if c in df.columns]

    if "test_sem_cnpj_zerado" in test_name:
        return df[df["CNPJ_Cliente"].astype(str).str.match(r"^0+$")][cols]

    if "test_sem_duplicatas_cnpj" in test_name:
        return df[df["CNPJ_Cliente"].duplicated(keep=False)][cols]

    if "test_sem_conversao_com_cevap" in test_name:
        return df[
            df["Status_Oportunidade"].str.contains("CONVERSÃO") & (df["Consultor"] == "CEVAP")
        ][cols]

    if "test_pendente_inativo_sempre_cevap" in test_name:
        return df[
            (df["Status_Oportunidade"] == "PENDENTE: INATIVO") & (df["Consultor"] != "CEVAP")
        ][cols]

    if "test_completude_consultor" in test_name:
        return df[df["Consultor"].isna()][cols]

    if "test_completude_cnpj" in test_name:
        return df[df["CNPJ_Cliente"].isna()][cols]

    if "test_dias_inativo_positivo" in test_name:
        return df[df["Dias_Inativo"] < 0][cols]

    return None

